from libcat.models import Record
from libcat.util.feed_format import as_list, first, parse_feed
from libcat.util.text import clean_title


class HarvestService:
    REQUIRED = ("id", "title")

    def __init__(self, repo, on_change=None):
        self.repo = repo
        self.on_change = on_change or (lambda: None)

    def ingest(self, text):
        added, updated, skipped = 0, 0, []
        for fields in parse_feed(text):
            missing = [k for k in self.REQUIRED if not fields.get(k)]
            if missing:
                skipped.append({"id": first(fields.get("id")), "missing": missing})
                continue
            record = self._to_record(fields)
            if self.repo.exists(record.id):
                updated += 1
            else:
                added += 1
            self.repo.save(record)
        if added or updated:
            self.on_change()
        return {"added": added, "updated": updated, "skipped": skipped}

    @staticmethod
    def _to_record(fields):
        return Record(
            id=first(fields["id"]),
            title=clean_title(first(fields["title"])),
            creators=as_list(fields.get("creator")),
            date=fields.get("date"),
            subjects=[s.lower() for s in as_list(fields.get("subject"))],
            language=first(fields.get("language")) or "und",
            publisher=first(fields.get("publisher")) or "",
        )
import datetime as dt
import unittest

from libcat.util.dates import display_year, parse_date, years_of


class DatesTest(unittest.TestCase):
    def test_parse_partial_dates(self):
        self.assertEqual(parse_date("2019"), dt.date(2019, 1, 1))
        self.assertEqual(parse_date("2019-05"), dt.date(2019, 5, 1))
        self.assertEqual(parse_date("2019.05.17"), dt.date(2019, 5, 17))
        self.assertIsNone(parse_date("2019-13-01"))
        self.assertIsNone(parse_date("spring 2019"))

    def test_years_of(self):
        self.assertEqual(years_of("2019-05-01"), {2019})
        self.assertEqual(years_of("1998"), {1998})
        self.assertEqual(years_of("c. 1900"), set())
        self.assertEqual(years_of(None), set())
        self.assertEqual(years_of(""), set())

    def test_display_year(self):
        self.assertEqual(display_year("2021-01"), "2021")
        self.assertEqual(display_year(None), "n.d.")

